// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.function.gql;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.junit.jupiter.api.Test;

class GqlBooleanFunctionTest {

	private static final String URI = "urn:rdf4j:gql:boolean";
	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void isRegisteredAndDeterministic() {
		assertThat(function().getDeterminism()).isEqualTo(Function.Determinism.DETERMINISTIC);
	}

	@Test
	void preservesTrueAndFalseWithoutChangingTheirRdfTerms() {
		for (Literal value : new Literal[] { VF.createLiteral(true), VF.createLiteral(false),
				VF.createLiteral("1", CoreDatatype.XSD.BOOLEAN), VF.createLiteral("0", CoreDatatype.XSD.BOOLEAN) }) {
			assertThat(function().evaluate(VF, value)).isSameAs(value);
		}
	}

	@Test
	void rejectsSparqlTruthinessForNonBooleanValues() {
		for (Value value : new Value[] { VF.createLiteral(1), VF.createLiteral(0), VF.createLiteral(1.0),
				VF.createLiteral("true"), VF.createLiteral("false"), VF.createLiteral(""), VF.createIRI("urn:node"),
				VF.createBNode("b") }) {
			assertThatThrownBy(() -> function().evaluate(VF, value))
					.isExactlyInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining("boolean");
		}
	}

	@Test
	void rejectsInvalidBooleanLexicalFormsAsAQueryFailure() {
		assertThatThrownBy(() -> function().evaluate(VF, VF.createLiteral("invalid", CoreDatatype.XSD.BOOLEAN)))
				.isExactlyInstanceOf(QueryEvaluationException.class);
	}

	@Test
	void anUnboundValueRemainsUnknown() {
		assertThatThrownBy(() -> function().evaluate(VF, (Value) null))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void requiresExactlyOneArgument() {
		assertThatThrownBy(() -> function().evaluate(VF)).isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> function().evaluate(VF, VF.createLiteral(true), VF.createLiteral(false)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	private static Function function() {
		var function = FunctionRegistry.getInstance().get(URI);
		assertThat(function).as("the strict GQL boolean function must be registered").isPresent();
		return function.orElseThrow();
	}
}
